body:
{
  "pains": [
    {
      "id": "pain:calling-people-who-left",
      "statement": "We pay for a contact database and half of it is wrong, so reps burn the morning on people who left the company or never worked there.",
      "element": "b2b:ease_of_doing_business:component_quality",
      "shape": {
        "surface": "Names, titles and numbers in the export do not match reality: the contact has moved on, the title is two roles old, the number rings someone else.",
        "operational": "Every list gets checked by hand before it is used, or against a second paid provider, which is the step buyers describe as not trusting the vendor's data without independently verifying it.",
        "personal": "One buyer says the leads embarrassed their company, which is the closest a public review gets to the personal cost: the rep's own credibility with their manager and with the prospect on the other end.",
        "personal_note": "Only one source reaches the personal rung, and it is company embarrassment rather than a named personal consequence. No public review read this run describes a performance review, a lost quarter or a conversation with a boss. The founder's own first calls are the place to fill this."
      },
      "workflow": "The list build itself: pull the search in ZoomInfo, Cognism or Seamless.AI, export to CSV, paste into the sequencer, and then at the step where the rep opens LinkedIn to sanity-check the row and finds the person is not there any more.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "The renewal quote arrives and the team measures what it paid against what bounced, which is when buyers start telling each other to watch the auto-renew clause.",
          "cites": ["src:7", "src:19"]
        }
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Good idea. Horrible data and accuracy.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "Outdated and inaccurate!",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "I would not trust Seamless.AI company data without independently verifying",
              "cites": ["src:13"]
            }
          ],
          "costs_them": "The hours in the day that were supposed to be conversations go to checking rows, and the rep still gets caught on the call knowing less than the prospect expects.",
          "fears": "That the next call is the one where they use a stale title out loud and the prospect writes them off.",
          "dream_outcome": "The row is right when it arrives, so the first thing they do with a list is send it, not audit it."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "over 50% of the data is out of date",
              "cites": ["src:6"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Most leads were so bad they embarrassed my company",
              "cites": ["src:12"]
            }
          ],
          "costs_them": "A line item paid in full for data the team only uses half of, plus the second provider bought to check the first.",
          "fears": "That they signed for a year on a number that will not hold up when someone asks what the contract bought.",
          "dream_outcome": "One bill where the accuracy is the thing being paid for, and no shadow spend on a second source to verify it."
        }
      },
      "segments": ["seg:lean", "seg:agency"],
      "feature_ref": "feat:waterfall",
      "feature_note": "Waterfall enrichment answers this by not depending on any single provider's freshness: running 200+ providers in cost order is the mechanical fix for the one-vendor-is-stale complaint these buyers make. The map cannot confirm that the waterfall result is fresher, only that the pain the feature claims to kill is the one buyers voice loudest.",
      "cites": ["src:1", "src:6", "src:10"]
    },
    {
      "id": "pain:half-the-cells-empty",
      "statement": "We paid for phone numbers and the export comes back without them, so the list looks big and is a third usable.",
      "element": "b2b:ease_of_doing_business:reach",
      "shape": {
        "surface": "Blank cells where the email or mobile should be, and a record count that flatters the list until you filter out the empties.",
        "operational": "A second and third provider gets bought to fill the gaps, or the rep goes back to LinkedIn and fills the row by hand; regions outside the provider's home market get skipped entirely.",
        "personal": null,
        "personal_note": "No public source read this run says what the empty cells cost the person. The reviews stop at the export. Asking a rep what they do on the day the list is half empty is the only way to fill this."
      },
      "workflow": "After the search and before the send: filter the Cognism or Smartlead export on the phone column, sort the blanks to the top, and count how many rows survive before the sequence can be loaded.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "The team pushes into a region the incumbent provider covers thinly, and an APAC or non-European search returns far fewer records than the same search at home.",
          "cites": ["src:9"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "it rarely has phone numbers and emails on it",
              "cites": ["src:8"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "export itself never comes with phone numbers",
              "cites": ["src:33"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "weaker coverage outside Europe, searching APAC turns up far fewer",
              "cites": ["src:9"]
            }
          ],
          "costs_them": "The list they were given is smaller than the target, so the day's activity target is unreachable before they start.",
          "fears": "That the gap gets read as them not working the list hard enough.",
          "dream_outcome": "A full row on every account that matters, without having to know which of five providers holds that particular field."
        }
      },
      "segments": ["seg:lean", "seg:agency"],
      "feature_ref": "feat:waterfall",
      "feature_note": "This is the pain waterfall enrichment is built for: coverage is the gap, not accuracy, and running providers in sequence until a field fills is a direct answer. The third quote here comes from a satisfied five-star buyer of a competitor, which is the useful kind of source: it is what still hurts after buying.",
      "cites": ["src:8", "src:33", "src:9"]
    },
    {
      "id": "pain:bounces-burn-the-domain",
      "statement": "A fifth of the emails we bought bounce, and after two campaigns the domain is on a blocklist and nothing we send arrives.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "Bounce counts in the double digits as a percentage, then sends that silently stop arriving, then the domain showing up on a public blocklist.",
        "operational": "Every purchased list goes through a separate verification tool before sending, secondary sending domains get bought and warmed, and campaigns get throttled to protect the main domain.",
        "personal": null,
        "personal_note": "The reviews name the damage to the sending asset, not to the person. No source read this run shows who gets blamed when the company domain stops delivering. That is a question for the founder's own customers."
      },
      "workflow": "The send itself: load the purchased list into Instantly or Smartlead, watch the bounce column climb over the first few hundred sends, then check the domain against SURBL or a blocklist lookup once replies stop coming.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "The sending domain appears on a public blocklist as abuse and mail starts being rejected outright, which turns a data problem into an outage.",
          "cites": ["src:34"]
        }
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "It has bounced soo many emails that it hurt my Email Reputation",
              "cites": ["src:32"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Domains appear on the SURBL.org blacklist as 'ABUSE' with emails being rejected",
              "cites": ["src:34"]
            },
            {
              "situation": "venting",
              "verbatim": "their own email go into spam and the worst part is their warm up tool",
              "cites": ["src:30"]
            }
          ],
          "costs_them": "The channel they are measured on goes dark, and the recovery is weeks of warming rather than a fix they can make on the day.",
          "fears": "That the domain damage is permanent and every future campaign inherits it.",
          "dream_outcome": "Sends that land because the addresses were good before they were sent, not because a verification tool caught them afterwards."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Highest inaccuracy and bounce rates out of all providers I've used (cognism, apollo, clay, hunter.io) around 17-40% bounces or risky emails.",
              "cites": ["src:15"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "hence we are in the market for a new provider",
              "cites": ["src:16"]
            }
          ],
          "costs_them": "Paying a data bill and a verification bill and a warmup bill to get one working channel, and measuring the provider by how much of its output has to be thrown away.",
          "fears": "That the company's ability to email anyone at all is being spent down by a vendor they chose.",
          "dream_outcome": "A bounce rate low enough that verification stops being a line item and the domain stops being a risk they manage."
        }
      },
      "segments": ["seg:lean", "seg:agency"],
      "feature_ref": "feat:waterfall",
      "feature_note": "Waterfall enrichment is the relevant feature because the bounce originates in the data, not the sender: fewer bad addresses leave the platform means fewer bounces to absorb. Nothing in the company artifact addresses the domain damage already done, which is where the buyer's urgency actually sits.",
      "cites": ["src:15", "src:32", "src:30"]
    },
    {
      "id": "pain:credits-gone-before-friday",
      "statement": "The credits disappear on runs I did not mean to start, and I cannot tell anyone what next month's data bill will be.",
      "element": "b2b:functional:cost_reduction",
      "shape": {
        "surface": "A credit balance dropping faster than the work done, charges for actions that felt like they should be free, and unused credits cut back at cancellation.",
        "operational": "Test runs get rationed, columns get rebuilt rather than re-run, someone keeps a tally of what each enrichment costs, and support gets chased for refunds that mostly do not come.",
        "personal": null,
        "personal_note": "The reviews are about money and trust in the vendor, not about what the overspend did to the person who approved it. No source read this run shows that. Worth asking whoever signed the last renewal."
      },
      "workflow": "Inside the table: add an enrichment column, change a filter, watch cells re-run, and find at the end of the week that the balance is spent on runs that were tests rather than output.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "Cancellation or downgrade, when accumulated credits the buyer had already paid for are cut back.",
          "cites": ["src:18", "src:17"]
        }
      ],
      "who_feels": ["economic_buyer", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "They take your unused credits that you paid for :)",
              "cites": ["src:17"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I had over 200 accumulated credits, but after cancelling my subscription, these were reduced to just 40 without this being made clear beforehand.",
              "cites": ["src:18"]
            },
            {
              "situation": "venting",
              "verbatim": "It is difficult to decipher the units provided by the literature and unclear what 40,000 means. You read unlimited and then are faced with 40,000.",
              "cites": ["src:28"]
            }
          ],
          "costs_them": "A variable bill they cannot forecast, on top of credits already paid for that get written off by the vendor's terms.",
          "fears": "That the spend runs away inside a quarter and they find out from finance rather than from the tool.",
          "dream_outcome": "Knowing before the month starts what the enrichment will cost, and keeping what they already bought."
        },
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Super poor interface, very complex search engines and eating credits for no reason.",
              "cites": ["src:22"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "they're stealing credit usage by running stuff that was never intended to run and then saying 'that's how the platform works'",
              "cites": ["src:21"]
            },
            {
              "situation": "venting",
              "verbatim": "charges credits when it is not necessary. It's called nickel and diming",
              "cites": ["src:29"]
            }
          ],
          "costs_them": "They stop experimenting, because every attempt costs money, so the tool gets used at a fraction of what it can do.",
          "fears": "That a mistake in a filter costs the team's month of credits and it will be traced to them.",
          "dream_outcome": "Being able to try a workflow without the trial itself being the expensive part."
        }
      },
      "segments": ["seg:lean", "seg:agency"],
      "feature_ref": null,
      "feature_note": "No feature in the company artifact removes this, and Clay is named by buyers as one of the offenders: the clearest quotes in this row are from Clay's own reviews alongside Lusha's and Apollo's. What would kill it is commercial, not technical: predictable pricing, a free place to test workflows, and credits that survive cancellation. The offer step and positioning's objections need this row more than the angles do.",
      "cites": ["src:21", "src:17", "src:29"]
    },
    {
      "id": "pain:locked-in-for-a-year",
      "statement": "We told them in the first month it was not working and we are still paying, now into year two.",
      "element": "b2b:ease_of_doing_business:flexibility",
      "shape": {
        "surface": "An auto-renewal that fires despite a cancellation request, a notice window that closed before anyone knew it existed, and charges continuing after the account was supposed to be shut.",
        "operational": "A paper trail gets kept on every cancellation conversation, calendar reminders get set against the notice window, and buyers warn each other about the clause in public reviews.",
        "personal": null,
        "personal_note": "No public review read this run says what the stuck contract did to the person who signed it. The nearest thing is a buyer keeping a paper trail, which implies they expect to have to defend the decision, but that is inference, not what they said."
      },
      "workflow": "Procurement rather than the product: the order form's auto-renew clause and notice period, the email to the account rep asking to cancel, and the invoice that arrives anyway sixty days later.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "The notice window before auto-renewal opens, which is when a buyer who wants out discovers whether they are already too late.",
          "cites": ["src:14", "src:11"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Terrible service, extremely difficult to cancel contracts.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "tried to back out within the first month and now we are on YEAR TWO",
              "cites": ["src:11"]
            },
            {
              "situation": "venting",
              "verbatim": "Watch the auto-renew clause. We have a paper trail that it was removed",
              "cites": ["src:7"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "Will not renew and looking for a new provider.",
              "cites": ["src:19"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I've tried to cancel for months in a row now and I keep getting charged",
              "cites": ["src:31"]
            }
          ],
          "costs_them": "A second year of spend on a tool already judged not to work, and the internal cost of arguing about it.",
          "fears": "That the same thing happens with the replacement, so the next signature is the one they get wrong twice.",
          "dream_outcome": "Paying month to month for as long as it works, and stopping the day it does not, without a notice period to defend."
        }
      },
      "segments": ["seg:lean", "seg:revops", "seg:agency"],
      "feature_ref": null,
      "feature_note": "This is a commercial term, not a feature, so nothing in the company artifact kills it. It is the single most repeated complaint across the incumbent vendors read this run and it is the switching trigger positioning should be built on: the alternative these buyers are currently suffering through is an annual contract they cannot leave.",
      "cites": ["src:3", "src:11", "src:7", "src:19"]
    },
    {
      "id": "pain:nobody-answers-when-it-breaks",
      "statement": "The thing is broken, I am paying every month, and the answer I get from support is to go read the docs or ask an LLM.",
      "element": "b2b:ease_of_doing_business:responsiveness",
      "shape": {
        "surface": "A ticket open for days or weeks, a help widget that does not open, and a reply that redirects to documentation rather than resolving the fault.",
        "operational": "Buyers spam the support channel to get any reply, debug the vendor's product themselves, ask the community instead, and in the meantime the campaign does not go out.",
        "personal": null,
        "personal_note": "The reviews describe the wait and the workaround, not the personal cost of it. No source read this run shows what the stalled launch did to the person waiting. Founder intake is the only way to get this."
      },
      "workflow": "Setup and the moment after a break: the in-app help button or support chat while the table, the sequence or the login is down, with the campaign that was supposed to launch that week sitting unsent.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "Onboarding stalls on a blocking bug and days of paid time accumulate with nothing sent.",
          "cites": ["src:35"]
        }
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "I have paid $350/m for several months, and when I needed support, their best answer was 'ask your LLM for help debugging'.",
              "cites": ["src:23"]
            },
            {
              "situation": "venting",
              "verbatim": "non-existent support - you are sent to read tons of docs whenever you have a simple question.",
              "cites": ["src:27"]
            }
          ],
          "costs_them": "Days of their own time spent doing the vendor's debugging, and a launch date that slips for reasons they cannot fix.",
          "fears": "That the next break lands in the middle of a campaign and they will again have no one to call.",
          "dream_outcome": "A person who answers the same day and knows the product better than they do."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Difficult company to do business with. Cannot reach anyone for support without making an appointment.",
              "cites": ["src:4"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "We have now wasted 23 days trying to get started",
              "cites": ["src:35"]
            }
          ],
          "costs_them": "Paid weeks with no output, and a team idle on a tool they authorised.",
          "fears": "That the contract runs while the value does not, and the renewal arrives before the product has ever worked.",
          "dream_outcome": "Support that is part of what they bought rather than something they have to escalate to get."
        }
      },
      "segments": ["seg:lean", "seg:agency"],
      "feature_ref": null,
      "feature_note": "No feature addresses this; it is a service commitment. It matters here because it is the pain that appears in Clay's own reviews as loudly as in the incumbents', which makes it an objection positioning has to answer rather than an angle to run.",
      "cites": ["src:23", "src:4", "src:27"]
    },
    {
      "id": "pain:personalise-or-scale-pick-one",
      "statement": "Either I read every prospect's posts myself and send twenty good emails, or I send two thousand generic ones and get told to remove them from the list.",
      "element": "b2b:ease_of_doing_business:reduced_effort",
      "shape": {
        "surface": "Two bad options with nothing in between: a small batch that took all week to research, or a large batch whose replies are opt-outs.",
        "operational": "The rep opens each prospect's LinkedIn and reads their recent posts before writing, so volume is capped by reading speed; when volume is forced, the personalisation is dropped and the sends go out generic.",
        "personal": null,
        "personal_note": "Neither source read this run says what this costs the person. This is the pain most likely to have a personal rung the founder can hear on a call, because the work is evenings, but no public source shows it and inventing it would be exactly the mistake this field exists to prevent."
      },
      "workflow": "Between the list and the send: a browser tab per account on LinkedIn and the company's own site, reading recent posts and news to find the one line that makes the email worth answering, then typing it into the sequencer row by row.",
      "type": "latent",
      "confidence": "medium",
      "revealed_by": "feat:claygents",
      "triggers": [
        {
          "event": "Acquisition cost comes under scrutiny, with 80% of surveyed sales professionals saying CAC is up or flat year over year, which makes the generic-volume option harder to defend.",
          "cites": ["src:38"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I used to read through prospects' LinkedIn posts manually to craft tailored outbound messages.",
              "cites": ["src:20"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "We got eight replies. Six of them were 'remove me from your list.'",
              "cites": ["src:36"]
            }
          ],
          "costs_them": "The whole week goes to reading rather than sending, or the sending happens and the replies are hostile; either way the pipeline number does not move.",
          "fears": "That the only way to hit the number is volume, and volume is what makes prospects hate them.",
          "dream_outcome": "Research done on every row without anyone reading it, so the good email and the large batch stop being alternatives."
        }
      },
      "segments": ["seg:lean", "seg:agency"],
      "feature_ref": "feat:claygents",
      "feature_note": "Latent rather than felt: neither source calls the manual reading a pain while doing it. One describes it as what they used to do, in hindsight, after seeing a tool that removes it, and the other describes the consequence of skipping it. AI research agents on each row are what make a buyer name it, which is why revealed_by and feature_ref are the same feature here.",
      "cites": ["src:20", "src:36"]
    },
    {
      "id": "pain:needs-a-specialist",
      "statement": "Finding a decision maker and their email turned into a project, and now someone on the team has to become the person who knows this tool.",
      "element": "b2b:ease_of_doing_business:simplification",
      "shape": {
        "surface": "A simple task that needs several configured steps, an interface that assumes prior knowledge, and an onboarding that hands the buyer documentation instead of a working setup.",
        "operational": "Someone learns the tool as a job, or a specialist is hired or contracted to run it, or a stack of narrower tools gets stitched together and babysat so it does not break on upgrade.",
        "personal": null,
        "personal_note": "The reviews say the tool is hard, not what being the person who owns it costs them. No public source read this run reaches the personal rung. A user who has become their team's tool owner would answer this in one sentence on a call."
      },
      "workflow": "The first week in the product: choosing a plan and a stack in setup, then building the first table or search, and getting stuck at the point where finding one decision maker's email needs several configured steps rather than one.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Self-serve onboarding with no guided setup, where the buyer is left to figure the product out alone.",
          "cites": ["src:5"]
        }
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "very bad experience, the workflow is very complicated",
              "cites": ["src:24"]
            },
            {
              "situation": "venting",
              "verbatim": "There is a real learning curve to using Clay efficiently, especially when it comes to reducing actions and credits",
              "cites": ["src:26"]
            },
            {
              "situation": "venting",
              "verbatim": "i used to build complex systems where I had to stitch tons of tools & had to stay on my toes just to ensure they don't break",
              "cites": ["src:25"]
            },
            {
              "situation": "venting",
              "verbatim": "useless search and AI assistant",
              "cites": ["src:27"]
            }
          ],
          "costs_them": "Weeks of learning before the tool produces anything, paid for at full price the whole time.",
          "fears": "That the skill is specific to one vendor, so the effort is wasted the moment the company switches.",
          "dream_outcome": "Getting the first useful list out on day one, and not being the only person who can run the stack."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Onboarding is sorely lacking. If you want an Amazon-styled self-service experience, go for it. You'll be left to figure it out!",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Licence spend running from day one against a team that cannot use the tool yet, plus the headcount or contractor needed to operate it.",
          "fears": "That the tool only works while the one person who learned it is still there.",
          "dream_outcome": "A tool the existing team can run without a dedicated operator, so the value does not depend on one hire."
        }
      },
      "segments": ["seg:lean", "seg:agency"],
      "feature_ref": null,
      "feature_note": "No feature removes this and Clay is named in it: two of the four end-user quotes here are Clay's own reviewers, including a five-star one. What would kill it is onboarding, templates and a place to learn that does not cost credits. Positioning has to treat this as the main objection, not an angle.",
      "cites": ["src:24", "src:27", "src:5"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "Buyers in these reviews name and rank several tools in one breath and say plainly that they are shopping for a replacement, which puts them past knowing the problem and past knowing solutions exist, but attached to an incumbent rather than to this product. One buyer lists five named providers with bounce rates for each; two others state they are in the market for a new provider. Nothing read this run shows a segment sitting somewhere else, so there is no per-segment override.",
      "cites": ["src:15", "src:16", "src:19"]
    }
  },
  "stats": [
    {
      "id": "stat:half-the-data-rots",
      "stat": "Buyers put the unusable share of purchased contact data at over half, and in the worst case read this run at roughly 98 percent.",
